int fib(int n) {                   // 이 함수가 모두 몇 번 호출되는가
    if (n <= 2) return 1;
    return fib(n - 1) + fib(n - 2);
}

// 계단을 한 번에 1칸 또는 2칸 오를 때 n칸에 오르는 방법의 수
d[1] = 1; d[2] = 2;
for (int i = 3; i <= n; i++)
    d[i] = d[i - 1] + d[i - 2];

// n을 1, 2, 3의 합으로 나타내는 방법의 수 (순서가 다르면 다른 방법)
d[1] = 1; d[2] = 2; d[3] = 4;
for (int i = 4; i <= n; i++)
    d[i] = d[i - 1] + d[i - 2] + d[i - 3];

// n을 1로 만드는 최소 연산 횟수 (3으로 나누기, 2로 나누기, 1 빼기)
d[1] = 0;
for (int i = 2; i <= n; i++) {
    d[i] = d[i - 1] + 1;
    if (i % 2 == 0) d[i] = min(d[i], d[i / 2] + 1);
    if (i % 3 == 0) d[i] = min(d[i], d[i / 3] + 1);
}

